        if (c == '\\') {
            if (i + 1 < str.length()) {
                char nextChar = str.charAt(i + 1);
                if (nextChar == 'n') {
                    sb.append('\n');
                    i++;
                } else if (nextChar == 'r') {
                    sb.append('\r');
                    i++;
                } else if (nextChar == 't') {
