    if (Character.isLetter(firstChar)) {
        // Append the first character to the buffer
        buf.append(firstChar);

        // Get the index of the next letter
        int nextLetterIndex = nameStart + 1;
        while (nextLetterIndex < buf.length() && !Character.isLetter(buf.charAt(nextLetterIndex))) {
            nextLetterIndex++;
